-- Registers the Gatcha Machine 3D model with Viewpoint's model packs so the
-- machine renders as a model in first person. Does nothing without Viewpoint.
-- The pack is generated by tools/viewpoint/gen_gatcha_model.ps1.

local MOD_ID = "LootBox"
local MANIFEST = "media/viewpoint/lootbox.properties"

local registered = false

local function register()
    if registered or not Viewpoint or not Viewpoint.ModelPacks then return end
    local ok, result = pcall(Viewpoint.ModelPacks.register, MOD_ID, MANIFEST)
    if ok and result then
        registered = true
        print("[LootBox] Registered Viewpoint model pack " .. MANIFEST)
    elseif not ok then
        print("[LootBox] Viewpoint model pack " .. MANIFEST .. ": " .. tostring(result))
    end
end

Events.OnGameBoot.Add(register)
Events.OnGameStart.Add(register)
register()
